style.css:
@-moz-document domain("YOUR_ADGUARD_IP") {
/* Fundo geral - Preto absoluto */
    body {
        background: #000 !important;
        color: #00ff00 !important;
        font-family: "Courier New", monospace !important;
    }

    /* Cartões e tabelas */
    .card, .table, .table th, .table td {
        background: #002200 !important;
        border-color: #004400 !important;
        color: #00ff00 !important;
        border-radius: 10px !important;
    }

    /* Cabeçalhos */
    h1, h2, h3, h4, h5, h6 {
        color: #00ff00 !important;
        text-shadow: 0 0 10px #00ff00 !important;
    }

    /* Botões */
    .btn {
        background: #004400 !important;
        border-color: #00ff00 !important;
        color: #00ff00 !important;
        text-transform: uppercase !important;
        border-radius: 8px !important;
    }

    .btn:hover {
        background: #007700 !important;
        border-color: #00ff00 !important;
        box-shadow: 0 0 10px #00ff00 !important;
    }

    /* Inputs e selects */
    input, select {
        background: #001100 !important;
        border: 1px solid #00ff00 !important;
        color: #00ff00 !important;
        font-family: "Courier New", monospace !important;
        border-radius: 8px !important;
        padding: 5px !important;
    }

    /* Links */
    a {
        color: #00ff00 !important;
        text-shadow: 0 0 5px #00ff00 !important;
    }

    a:hover {
        color: #33ff33 !important;
        text-shadow: 0 0 15px #00ff00 !important;
    }

    /* Barra superior */
    .navbar {
        background: #001100 !important;
        border-bottom: 2px solid #00ff00 !important;
        box-shadow: 0 0 10px #00ff00 !important;
        border-radius: 0 0 10px 10px !important;
    }

    /* Menu lateral */
    .sidebar {
        background: #000 !important;
        border-radius: 10px !important;
    }

    .sidebar a {
        color: #00ff00 !important;
        border-radius: 8px !important;
    }

    .sidebar a:hover {
        background: #003300 !important;
        box-shadow: 0 0 10px #00ff00 !important;
    }

    /* Gráficos */
    .chart {
        background: #000 !important;
        border: 1px solid #00ff00 !important;
        box-shadow: 0 0 15px #00ff00 !important;
        border-radius: 10px !important;
    }

    /* ?️ Efeito Matrix - Chuva de Código */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: black;
        z-index: -1;
        opacity: 1;
        overflow: hidden;
    }

    body::after {
        content: " ";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        pointer-events: none;
        background: linear-gradient(to bottom, transparent, rgba(0, 255, 0, 0.3), black),
                    repeating-linear-gradient(to bottom, rgba(0, 255, 0, 0.1) 0px, transparent 3px);
        animation: matrixRain 1s linear infinite;
        z-index: -1;
    }

    @keyframes matrixRain {
        0% { transform: translateY(-100vh); }
        100% { transform: translateY(100vh); }
    }
}
